chunk:
OrderLine:
  type: object
  required: [lineId, productId, quantity, unitPrice]
  properties:
    lineId:        { type: string }
    productId:     { type: string, description: "Canonical product identifier" }
    sku:           { type: string }
    description:   { type: string }
    quantity:      { type: number, minimum: 0 }
    unitPrice:     { type: number, minimum: 0 }
    discount:      { type: number, minimum: 0, maximum: 100, description: "Percentage" }
    lineTotal:     { type: number, description: "quantity × unitPrice × (1 - discount/100)" }
    taxCode:       { type: string }
    taxAmount:     { type: number }

OrderTotals:
  type: object
  required: [subtotal, total, currency]
  properties:
    subtotal:    { type: number }
    discount:    { type: number }
    tax:         { type: number }
    shipping:    { type: number }
    total:       { type: number }
    currency:    { type: string, pattern: "^[A-Z]{3}$", example: "USD" }

OrderFulfillment:
  type: object
  properties:
    type:            { type: string, enum: [SHIP, PICKUP, DIGITAL, SERVICE] }
    warehouseId:     { type: string }
    shippingAddress: { $ref: '#/Address' }
    carrier:         { type: string }
    trackingNumber:  { type: string }
    estimatedDate:   { type: string, format: date }
    actualDate:      { type: string, format: date }

BillingInfo:
  type: object
  properties:
    billingAddress:  { $ref: '#/Address' }
    paymentTerms:    { type: string, example: "NET30" }
    paymentMethod:   { type: string, enum: [INVOICE, CREDIT_CARD, ACH, CHECK, WIRE] }

Address:
  type: object
  properties:
    line1:      { type: string }
    line2:      { type: string }
    city:       { type: string }
    state:      { type: string }
    postalCode: { type: string }
    country:    { type: string, pattern: "^[A-Z]{2}$", example: "US" }

Timestamps:
  type: object
  properties:
    createdAt:   { type: string, format: date-time }
    updatedAt:   { type: string, format: date-time }
    submittedAt: { type: string, format: date-time }
    approvedAt:  { type: string, format: date-time }
    fulfilledAt: { type: string, format: date-time }
    closedAt:    { type: string, format: date-time }
